import json

# Retrieve all billing logs
logs = []
offset = 0
while True:
    resp = query_logs(service='billing', level='INFO', limit=200, offset=offset)
    logs.extend(resp['items'])
    if resp['total'] <= offset + resp['limit']:
        break
    offset += resp['limit']

# Filter overdue invoices for customer Birch with amount > 1000
overdue_invoices = []
for entry in logs:
    # Example log format: {"ts":"2023-09-15T12:34:56Z","service":"billing","level":"INFO","msg":"Invoice paid for customer Birch: amount=1500, invoice_id=INV12345"}
    msg = entry['msg']
    # Extract customer name and amount
    if 'customer Birch' in msg:
        # Simple parsing: assume amount is after "amount=" and before the next comma or end
        amount_start = msg.find('amount=') + len('amount=')
        amount_end = msg.find(',', amount_start)
        if amount_end == -1:
            amount_end = len(msg)
        amount_str = msg[amount_start:amount_end]
        try:
            amount = float(amount_str)
            if amount > 1000:
                overdue_invoices.append({
                    'amount': amount,
                    'msg': msg
                })
        except ValueError:
            continue

# Output the count of such invoices
print(len(overdue_invoices))

