import json

def get_open_issues_assignees(repo):
    assignees = {}
    # fetch up to 100 open issues (max limit)
    offset = 0
    while True:
        resp = list_issues(repo=repo, state='open', limit=100, offset=offset)
        items = resp['items']
        if not items:
            break
        for issue in items:
            assignee = issue.get('assignee')
            if assignee:
                assignees[assignee] = assignees.get(assignee, 0) + 1
        offset += len(items)
        if len(items) < 100:
            break
    return assignees

assignee_counts = get_open_issues_assignees('beacon')
if not assignee_counts:
    print("No open issues with assignees.")
else:
    max_count = max(assignee_counts.values())
    # get any assignee(s) with max count
    max_assignees = [assignee for assignee, cnt in assignee_counts.items() if cnt == max_count]
    # lookup full name
    names = []
    for assignee_id in max_assignees:
        user_info = lookup_user(assignee_id)
        names.append(user_info['name'])
    # output full name(s)
    print(names[0])

