import re

def sum_totals(directory):
    total_sum = 0
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.txt'):  # assuming report files are .txt
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    lines = f.readlines()
                    # Find the line that ends with 'TOTAL: <number>'
                    for line in lines:
                        if line.strip().endswith('TOTAL:'):
                            # Extract the number after 'TOTAL:'
                            match = re.search(r'TOTAL:\s*(\d+)$', line)
                            if match:
                                total_sum += int(match.group(1))
    return total_sum

